import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { YAML } from 'bun';

const HEADER =
  '/* Generated by scripts/build.mjs from DESIGN.md front matter. Do not edit by hand. */';
const DARK_PREFIX = 'dark-';
const REQUIRED_GROUPS = ['colors', 'typography', 'spacing', 'rounded', 'components'];

function assertTokenGroup(tokens, group) {
  const value = tokens[group];
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`missing required token group: ${group}`);
  }
  if (Object.keys(value).length === 0) {
    throw new Error(`missing required token group: ${group} (group is empty)`);
  }
}

function assertColorPairs(colors) {
  const names = Object.keys(colors);
  for (const name of names) {
    if (name.startsWith(DARK_PREFIX)) {
      const base = name.slice(DARK_PREFIX.length);
      if (!names.includes(base)) {
        throw new Error(`unpaired dark color: ${name} has no base color ${base}`);
      }
    } else if (!names.includes(`${DARK_PREFIX}${name}`)) {
      throw new Error(
        `unpaired base color: ${name} has no dark color ${DARK_PREFIX}${name}`,
      );
    }
  }
}

function validateTokens(tokens) {
  if (tokens === null || typeof tokens !== 'object' || Array.isArray(tokens)) {
    throw new Error('invalid front matter: expected a YAML mapping');
  }
  for (const group of REQUIRED_GROUPS) {
    assertTokenGroup(tokens, group);
  }
  assertColorPairs(tokens.colors);
}

function formatColor(value) {
  return String(value).trim().toLowerCase();
}

function formatDimension(value) {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return `${value}px`;
  }
  return String(value).trim();
}

function createEmitter(lines) {
  const seen = new Set();
  return (variable, value) => {
    if (seen.has(variable)) {
      throw new Error(`duplicate variable name: ${variable}`);
    }
    seen.add(variable);
    lines.push(`  ${variable}: ${value};`);
  };
}

function emitColors(entries) {
  const lines = [];
  const emit = createEmitter(lines);
  for (const [name, value] of entries) {
    emit(`--color-${name}`, formatColor(value));
  }
  return lines;
}

function emitTypography(typography) {
  const lines = [];
  const emit = createEmitter(lines);
  for (const [type, spec] of Object.entries(typography)) {
    if (spec === null || typeof spec !== 'object' || Array.isArray(spec)) {
      throw new Error(`invalid typography token: ${type} must be a mapping`);
    }
    if (spec.fontFamily !== undefined) {
      emit(`--font-${type}`, String(spec.fontFamily).trim());
    }
    if (spec.fontSize !== undefined) {
      emit(`--text-${type}-size`, formatDimension(spec.fontSize));
    }
    if (spec.fontWeight !== undefined) {
      emit(`--text-${type}-weight`, String(spec.fontWeight).trim());
    }
    if (spec.lineHeight !== undefined) {
      emit(`--text-${type}-line-height`, String(spec.lineHeight).trim());
    }
    if (spec.letterSpacing !== undefined) {
      emit(`--text-${type}-letter-spacing`, String(spec.letterSpacing).trim());
    }
    if (spec.fontFeature !== undefined) {
      emit(`--text-${type}-font-feature`, String(spec.fontFeature).trim());
    }
  }
  return lines;
}

function emitScale(prefix, group) {
  const lines = [];
  const emit = createEmitter(lines);
  for (const [name, value] of Object.entries(group)) {
    emit(`--${prefix}-${name}`, formatDimension(value));
  }
  return lines;
}

/**
 * Bun's YAML parser keeps the last value for a duplicate key. The design system
 * treats a duplicate key as an error, so scan the block mapping before parsing.
 */
function assertNoDuplicateKeys(source) {
  const levels = [];
  for (const line of source.split('\n')) {
    if (!line.trim() || line.trimStart().startsWith('#')) continue;
    const match = line.match(/^(\s*)([^:\s][^:]*?):(?:\s|$)/);
    if (!match) continue;
    const indent = match[1].length;
    const key = match[2].trim().replace(/^["']|["']$/g, '');
    if (!/^[A-Za-z0-9_.-]+$/.test(key)) continue;

    while (levels.length && levels[levels.length - 1].indent > indent) {
      levels.pop();
    }
    if (!levels.length || levels[levels.length - 1].indent < indent) {
      levels.push({ indent, keys: new Set() });
    }
    const level = levels[levels.length - 1];
    if (level.keys.has(key)) {
      throw new Error(`duplicate variable name: ${key}`);
    }
    level.keys.add(key);
  }
}

/**
 * Reads DESIGN.md YAML front matter into a validated token tree.
 */
export function readDesignTokens(markdown) {
  if (typeof markdown !== 'string') {
    throw new TypeError('readDesignTokens expects a markdown string');
  }
  const source = markdown.replace(/\r\n?/g, '\n');
  if (!source.startsWith('---\n')) {
    throw new Error(
      'missing front matter: DESIGN.md must start at byte 0 with a --- fence',
    );
  }
  const end = source.indexOf('\n---', 3);
  if (end === -1) {
    throw new Error('unterminated front matter: missing closing --- fence');
  }
  const after = source.slice(end + 4);
  if (after !== '' && !after.startsWith('\n')) {
    throw new Error('malformed front matter: closing --- fence must end its line');
  }

  const yamlSource = source.slice(4, end);
  assertNoDuplicateKeys(yamlSource);
  let tokens;
  try {
    tokens = YAML.parse(yamlSource);
  } catch (error) {
    throw new Error(`invalid front matter: ${error.message}`);
  }

  validateTokens(tokens);
  return tokens;
}

/**
 * Renders validated tokens as deterministic light/dark CSS.
 */
export function renderTokensCss(tokens) {
  validateTokens(tokens);

  const colorEntries = Object.entries(tokens.colors);
  const lightColors = colorEntries.filter(([name]) => !name.startsWith(DARK_PREFIX));
  const darkColors = colorEntries
    .filter(([name]) => name.startsWith(DARK_PREFIX))
    .map(([name, value]) => [name.slice(DARK_PREFIX.length), value]);

  const rootLines = [
    '  color-scheme: light;',
    ...emitColors(lightColors),
    ...emitTypography(tokens.typography),
    ...emitScale('space', tokens.spacing),
    ...emitScale('radius', tokens.rounded),
  ];

  const darkLines = [
    '  color-scheme: dark;',
    ...emitColors(darkColors),
  ];
  const mediaLines = darkLines.map((line) => `  ${line}`);

  const rootBlock = `:root {\n${rootLines.join('\n')}\n}`;
  const darkBlock = `[data-theme="dark"] {\n${darkLines.join('\n')}\n}`;
  const mediaBlock = [
    '@media (prefers-color-scheme: dark) {',
    '  :root:not([data-theme]) {',
    mediaLines.join('\n'),
    '  }',
    '}',
  ].join('\n');

  return [HEADER, rootBlock, darkBlock, mediaBlock].join('\n\n') + '\n';
}

async function main() {
  const root = process.cwd();
  const markdown = await readFile(join(root, 'DESIGN.md'), 'utf8');
  const css = renderTokensCss(readDesignTokens(markdown));
  const outDir = join(root, 'dist');
  await mkdir(outDir, { recursive: true });
  await writeFile(join(outDir, 'tokens.css'), css, 'utf8');
}

const invokedPath = process.argv[1];
if (invokedPath && pathToFileURL(invokedPath).href === import.meta.url) {
  main().catch((error) => {
    console.error(`build failed: ${error.message}`);
    process.exitCode = 1;
  });
}
